import ast,base64,copy,hashlib,json,subprocess
from pathlib import Path
p=json.load(open('/private/tmp/wf139-delivery/packet-draft.json'))
path='.wavefoundry/framework/scripts/render_agent_surfaces.py'
a=ast.parse(subprocess.check_output(['git','show','HEAD:'+path],text=True));b=ast.parse(Path(path).read_text())
def normalize(tree):
 for n in ast.walk(tree):
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='Skill' and any(k.arg=='name' and isinstance(k.value,ast.Constant) and k.value.value=='wf-envision' for k in n.keywords):
   for k in n.keywords:
    if k.arg=='description': k.value=ast.Constant(value='DESCRIPTION')
    if k.arg=='body': k.value.args[2].elts[0]=ast.Constant(value='FIRST BULLET')
 return ast.dump(tree,include_attributes=False)
assert normalize(a)==normalize(b),'Executable/registration change beyond two literals'
# Adjacent bad control changes the backing registration gate, which must fail.
bad=copy.deepcopy(b)
for n in ast.walk(bad):
 if isinstance(n,ast.keyword) and n.arg=='requires_doc' and isinstance(n.value,ast.Constant) and n.value.value=='docs/prompts/envision-project.prompt.md': n.value.value='docs/prompts/unrelated.prompt.md'
assert normalize(a)!=normalize(bad),'Bad registration control survived'
e=json.load(open('docs/waves/21xq1 envision-grounded-priorities/evaluation-evidence.json'))['isolated_ac3_completion']
def snapshot(s):
 out={}
 for name,item in s['files'].items():
  data=base64.b64decode(item['bytes_base64']);assert hashlib.sha256(data).hexdigest()==item['sha256'];assert len(data)==item['size'];out[name]=data
 return out
before=snapshot(e['before']);after=snapshot(e['after_author']);reader=snapshot(e['after_reader'])
assert len(before)==8 and before==after==reader
assert e['before']['directories']==e['after_author']['directories']==e['after_reader']['directories']
root=Path(e['before']['root']);live={str(x.relative_to(root)):x.read_bytes() for x in root.rglob('*') if x.is_file()}
assert live==before
bad_snapshot=dict(after);sentinel=next(x for x in after if x.endswith('wave.md'));bad_snapshot[sentinel]+=b'altered'
assert before!=bad_snapshot,'Bad lifecycle sentinel control survived'
assert Path('docs/prompts/envision-project.prompt.md').read_bytes()==before['candidate-envision.prompt.md']
result={'renderer_ast':'identical except expected description and first-bullet literal values','negative_registration_gate':'detected','recorded_snapshots':'8 files byte-identical across before, after author, after reader; embedded hashes valid; same directory list','current_fixture':'8 file bytes match retained before snapshot','negative_lifecycle_sentinel':'detected','prompt':'retained fixture prompt matches current local prompt','scope':'closest faithful syntax boundary and retained AC3 observations; not a renderer invocation, new authoring trial, historical tool trace or network enforcement'}
hashes={x:subprocess.check_output(['git','hash-object',x],text=True).strip() for x in p['files_in_scope']};assert hashes==p['tree_fingerprint'];result['after_fingerprints']=hashes
Path('/private/tmp/wf139-delivery/security-check-results.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
